          visible = true,
          properties = {
            ["atMostOnce"] = true,
            ["script"] = "local BlockPlayer = require \"actions/BlockPlayer\"\nlocal MessageBox = require \"actions/MessageBox\"\nlocal Animate = require \"actions/Animate\"\nlocal Do = require \"actions/Do\"\nlocal Serial = require \"actions/Serial\"\nlocal Parallel = require \"actions/Parallel\"\nlocal Ease = require \"actions/Ease\"\nlocal Wait = require \"actions/Wait\"\nlocal AudioFade = require \"actions/AudioFade\"\nlocal PlayAudio = require \"actions/PlayAudio\"\nlocal Spawn = require \"actions/Spawn\"\n\nlocal Transform = require \"util/Transform\"\nlocal SpriteNode = require \"object/SpriteNode\"\n\nreturn function(self)\n    self.scene.player.x = 380\n    walkout, walkin, sprites = self.scene.player:split(nil, true)\n    for k in pairs(GameState.party) do\n        sprites[k].x = self.scene.player.x - 60\n        sprites[k].y = self.scene.player.y - 60\n    end\n    local storybook = SpriteNode(scene, Transform(0, 0, 1, 1), {255,255,255,0}, \"storybook3\", nil, nil, \"ui\")\n    return BlockPlayer {\n        AudioFade(\"music\", 1, 0, 1),\n        walkout,\n        Do(function()\n            sprites.b.x = sprites.b.x + 50\n        end),\n        Animate(sprites.b.sprite, \"idleright\"),\n        Animate(sprites.babyt.sprite, \"idleleft\"),\n        Animate(sprites.tails.sprite, \"reading\"),\n        MessageBox{message=\"Tails: I think we're getting close...\"},\n        Ease(storybook.color, 4, 255, 1),\n        Wait(1),\n        MessageBox{message=\"Tails: In the next part of the story, Ben and the Knight are approaching a bright light...\"},\n        Ease(storybook.color, 4, 0, 1),\n\n        PlayAudio(\"sfx\", \"elevator\", 1.0, true),\n        Parallel {\n            Serial {\n                Wait(1),\n                Animate(sprites.tails.sprite, \"idledown\"),\n                Wait(1),\n                MessageBox{message=\"Baby T: What is that?\", closeAction=Wait(1.5)},\n                MessageBox{message=\"Tails: Whatever it is{p60}, it sounds like it's coming closer!\", closeAction=Wait(1.5)},\n            },\n            self.scene:screenShake(10, 30, 140)\n        },\n       -- Drill bursts onto scene\n       PlayAudio(\"sfx\", \"explosion\", 1, true),\n       self.scene:screenShake(25, 40),\n       Ease(self.scene.objectLookup.Drill, \"x\", function() return self.scene.objectLookup.Drill.x + 200 end, 5, \"quad\"),\n       Animate(sprites.b.sprite, \"shock\"),\n       Animate(sprites.babyt.sprite, \"shock\"),\n       Animate(sprites.tails.sprite, \"shock\"),\n       Parallel {\n            sprites.b:hop(),\n            sprites.babyt:hop(),\n            sprites.tails:hop()\n        },\n        Wait(1),\n        Parallel {\n            Ease(self.scene.objectLookup.Drill, \"x\", function() return self.scene.objectLookup.Drill.x - 250 end, 1),\n            Ease(self.scene.camPos, \"y\", function() return self.scene.camPos.y - 100 end, 1)\n        },\n\n        Animate(sprites.b.sprite, \"leap\"),\n        Animate(sprites.babyt.sprite, \"idle\"),\n        Animate(sprites.tails.sprite, \"leap\"),\n        Parallel {\n            Ease(sprites.babyt, \"y\", function() return sprites.babyt.y + 30 end, 3),\n            Ease(sprites.b, \"x\", function() return sprites.babyt.x + 60 end, 3),\n            Ease(sprites.tails, \"x\", function() return sprites.babyt.x + 60 end, 3),\n            Serial {\n                Parallel {\n                    Ease(sprites.b, \"y\", function() return sprites.b.y - 50 end, 3),\n                    Ease(sprites.tails, \"y\", function() return sprites.tails.y - 50 end, 3)\n                },\n                Parallel {\n                    Ease(sprites.b, \"y\", function() return sprites.b.y + 200 end, 3),\n                    Ease(sprites.tails, \"y\", function() return sprites.tails.y + 130 end, 3)\n                },\n            }\n       },\n       Animate(sprites.b.sprite, \"crouch\"),\n       Animate(sprites.tails.sprite, \"crouch\"),\n       Wait(0.1),\n       Animate(sprites.b.sprite, \"idle\"),\n       Animate(sprites.tails.sprite, \"slap_idle\"),\n\n        Wait(2),\n        MessageBox{message=\"Well, well... {p60}what do we have here?\", textSpeed=3},\n        PlayAudio(\"music\", \"robotnik\", 1, true, true),\n\n        Do(function() self.scene.objectLookup.Robotnik.sprite:setAnimation(\"walkright\") end),\n        Ease(self.scene.objectLookup.Robotnik, \"x\", function() return self.scene.objectLookup.Robotnik.x + 260 end, 0.3, \"linear\"),\n        Animate(self.scene.objectLookup.Robotnik.sprite, \"idleright\"),\n        MessageBox{message=\"Tails: Robotnik!\"},\n        MessageBox{message=\"Robotnik: Ah yes...{p40}you were the three I saw on the cliffs of the Great Jungle...\", textSpeed=3},\n        MessageBox{message=\"Robotnik: I gave you the pleasure of being the first victims of my latest creation...\", textSpeed=3},\n        Ease(self.scene.objectLookup.Terrabot, \"x\", function() return self.scene.objectLookup.Terrabot.x + 130 end, 0.2),\n        MessageBox{message=\"Robotnik: And here he is... {p60}truly a work of art, wouldn't you agree?\", textSpeed=3},\n        Parallel {\n            Animate(sprites.babyt.sprite, \"roar\"),\n            MessageBox{message=\"Baby T: You didn't create anything! {p60}That's my uncle!\"}\n        },\n        MessageBox{message=\"Robotnik: The little beast speaks...\", textSpeed=2},\n        MessageBox{message=\"Robotnik: You so narrowly survived your last encounter with the old boy...{p60} perhaps it's time for round\\ntwo?\", textSpeed=3},\n        Do(function() self.scene.partySprites = sprites end),\n        AudioFade(\"music\", 1, 0, 1),\n        self.scene:enterBattle {\n            opponents = {\"terrabot2\"},\n            initiative = \"cinematic\",\n            hint = \"after_terrabot\",\n            music = \"roboterrapod\"\n        }\n    }\nend"
